import { expect, test, uniqueName } from "../../fixtures";

test.describe("Vendor audit trail", () => {
  test("audit trails from another tenant are invisible", { tag: "@AUD-02" }, async ({ apiAs }) => {
    // Arrange: a vendor that exists in the Globex Procurement tenant
    const globex = await apiAs("otherTenant");
    const name = uniqueName("Globex Audit");
    const created = await globex.post("/api/vendors", {
      data: {
        name,
        category: "services",
        contact_email: `globex.audit.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = (await created.json()) as { id: string };

    // Act: Northwind member requests that vendor's audit trail
    const member = await apiAs("member");
    const response = await member.get(`/api/vendors/${vendor.id}/audit`);

    // Assert
    expect(response.status(), await response.text()).toBe(404);
  });
});
